def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive = []
    prev_bids = []
    dangerous_affordable = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) >= bid * 0.8:
                    dangerous_affordable.append(float(bid))

    if not alive:
        return min(budget, 20)

    competitors = len(alive) + 1
    expected_share = supply / float(competitors)
    scarcity = WATER_REQ / max(1.0, expected_share)

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days >= 1:
        urgency += 0.45
    if day >= 8:
        urgency += 0.2

    base = DAILY_SALARY * 0.42
    if scarcity > 1.35:
        base = DAILY_SALARY * 0.9
    elif scarcity > 1.1:
        base = DAILY_SALARY * 0.68
    elif scarcity < 0.8:
        base = DAILY_SALARY * 0.28

    if dangerous_affordable:
        target = max(dangerous_affordable)
    elif prev_bids:
        target = max(prev_bids)
    else:
        target = DAILY_SALARY * 0.5

    if urgency >= 1.5:
        bid = max(base, min(target + 2.0, DAILY_SALARY * 1.55))
    elif urgency >= 0.7:
        bid = max(base, min(target * 0.82 + 3.0, DAILY_SALARY * 1.15))
    else:
        if scarcity < 0.9:
            bid = min(base, DAILY_SALARY * 0.35)
        else:
            bid = max(base, min(target * 0.62 + 2.0, DAILY_SALARY * 0.9))

    if budget < DAILY_SALARY * 0.6 and urgency < 1.0:
        bid = min(bid, budget * 0.55)
    elif budget < DAILY_SALARY and urgency < 1.5:
        bid = min(bid, budget * 0.75)

    if hp <= 1 or no_water_days >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 1.2))

    if day == 1 and supply >= 22:
        bid = min(bid, DAILY_SALARY * 0.3)

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 1)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer aggressiveness
    prev_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline target: secure water when tight supply / low hp
    # Supply tiers: 15-18 tight, 19-22 medium, 23-25 loose
    if supply <= 18.0:
        tier = 0
    elif supply <= 22.0:
        tier = 1
    else:
        tier = 2

    # Pressure from opponents: if someone bid very high yesterday, they likely overvalue survival
    high_prev = max(prev_bids) if prev_bids else 0.0

    # My urgency
    # If I'm already accumulating no-water days, increase bid.
    urgency = 0
    if hp <= 2:
        urgency += 2
    elif hp <= 4:
        urgency += 1
    if no_water_days >= 2:
        urgency += 1

    # Compute a bid cap based on budget and urgency
    # Keep below aggressive bids unless necessary.
    # Use int() for any potential indexing (none used here).
    if tier == 0:
        base = DAILY_SALARY * 0.65
    elif tier == 1:
        base = DAILY_SALARY * 0.55
    else:
        base = DAILY_SALARY * 0.45

    # If opponents were bidding extremely high yesterday, slightly undercut unless I'm critical.
    # Eric's low bids suggest some may not spend; don't overreact to a single high value.
    if high_prev >= DAILY_SALARY * 1.3:
        # Cindy-like behavior: raise a bit, but still try to stay cost-effective.
        base += DAILY_SALARY * 0.15

    # Urgency adjustment
    base += urgency * (DAILY_SALARY * 0.18)

    # If supply is so tight that winning likely requires more, push further.
    # Rough heuristic: if supply < 2*WATER_REQ, competition is higher.
    if supply < float(2 * WATER_REQ):
        base += DAILY_SALARY * 0.10

    # Final bid: never exceed budget
    bid = float(min(budget, base))

    # If budget is tiny, bid whatever we can.
    if bid <= 0.0:
        return 0.0

    return bid

